a-harden-route-handler.prompt:
This route file is already in production and it keeps biting us: a malformed POST /users body returns a 500 with a stack trace instead of a 400, and last week someone imported a batch where `age` came through as a string and nothing complained. `role` in our system is always one of `admin`, `editor` or `viewer`, `email` must be a real email address, and `metadata` is a free-form JSON blob we only ever forward to the analytics queue. Go through this file and give me the fixed version plus a short explanation of what was wrong with each thing you changed.

```typescript
// server/src/routes/users.ts
import { z } from 'zod'
import type { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify'
import { db } from '../db.js'

const configSchema = z.object({
  DATABASE_URL: z.string().url(),
  MAX_UPLOAD_MB: z.coerce.number().int().positive(),
})
export const config = configSchema.parse(process.env)

const createUserSchema = z.object({
  email: z.string(),
  name: z.string(),
  age: z.number(),
  role: z.string(),
  metadata: z.any(),
})

interface CreateUserInput {
  email: string
  name: string
  age: number
  role: string
  metadata: any
}

export async function registerUserRoutes(app: FastifyInstance) {
  app.post('/users', async (req: FastifyRequest, reply: FastifyReply) => {
    const input: CreateUserInput = createUserSchema.parse(req.body)
    const user = await db.users.create({ data: input })
    return reply.code(201).send(user)
  })

  app.post('/users/import', async (req, reply) => {
    const raw = (req.body as { payload: string }).payload
    const rows = JSON.parse(raw) as CreateUserInput[]
    for (const row of rows) {
      await db.users.create({ data: row })
    }
    return reply.send({ imported: rows.length })
  })
}

export function toErrorResponse(err: z.ZodError) {
  return { message: err.issues[0].message }
}
